#include <iostream>
#include <string>
using namespace std;

class Cat {
    string name;
    int fish;
public:
    Cat(string n, int f) : name(n), fish(f) {}
    friend void showAccount(const Cat& c);
};

void showAccount(const Cat& c) {
    cout << c.name << " 的账上是 " << c.fish << " 条小鱼干喵" << endl;
}

int main() {
    string name;
    int fish = 0;
    cin >> name >> fish;

    Cat c1(name, fish);
    showAccount(c1);
    return 0;
}
